const TWO_FACTOR_BASE_URL = "https://2factor.in/API/V1";
const TWO_FACTOR_TEMPLATE = "BLUEBELL_OTP";
const SMS_REQUEST_TIMEOUT_MS = 10_000;

/**
 * Normalizes a validated 10-digit Indian mobile number to the +91
 * international format required by the 2Factor SMS API.
 */
function normalizeToInternationalFormat(phone: string): string {
  return `+91${phone}`;
}

/**
 * Sends a custom OTP via the 2Factor SMS API.
 *
 * @param phone - A validated 10-digit Indian mobile number (no country code).
 * @param otp - The 6-digit OTP value already generated by the caller.
 * @returns true only when the provider reports a successful submission.
 *
 * Reads the API key exclusively from process.env.TWOFACTOR_API_KEY. Missing
 * configuration, provider errors, invalid responses, and network timeouts all
 * fail closed (false). No API key, OTP, or full request URL is ever logged.
 */
export async function sendOtpSms(phone: string, otp: string): Promise<boolean> {
  const apiKey = process.env.TWOFACTOR_API_KEY?.trim();
  if (!apiKey) {
    return false;
  }

  const normalizedPhone = normalizeToInternationalFormat(phone);

  const url = [
    TWO_FACTOR_BASE_URL,
    encodeURIComponent(apiKey),
    "SMS",
    encodeURIComponent(normalizedPhone),
    encodeURIComponent(otp),
    encodeURIComponent(TWO_FACTOR_TEMPLATE),
  ].join("/");

  try {
    const response = await fetch(url, {
      method: "GET",
      signal: AbortSignal.timeout(SMS_REQUEST_TIMEOUT_MS),
    });

    if (!response.ok) {
      return false;
    }

    const data = (await response.json()) as {
      Status?: string;
      Details?: string;
    };
    return data.Status === "Success";
  } catch {
    return false;
  }
}
